import * as THREE from './assets/three.module.js';
export function addPassageStorage(scene){const walnut=new THREE.MeshStandardMaterial({color:'#4c3a2e',roughness:.83}),front=new THREE.MeshStandardMaterial({color:'#b8a68c',roughness:.82}),bronze=new THREE.MeshStandardMaterial({color:'#907451',metalness:.55,roughness:.4}),glass=new THREE.MeshPhysicalMaterial({color:'#b8b4a6',roughness:.1,transparent:true,opacity:.22,depthWrite:false}),warm=new THREE.MeshStandardMaterial({color:'#ffe2b0',emissive:'#ffd18f',emissiveIntensity:.9});
 function mesh(g,geo,m,x,y,z){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=!m.transparent;o.receiveShadow=true;g.add(o);return o;}
 const box=(g,w,h,d,x,y,z,m=walnut)=>mesh(g,new THREE.BoxGeometry(w,h,d),m,x,y,z);
 function cabinet(name,x,z,w,d,h){const g=new THREE.Group();g.name=name;g.position.set(x,0,z);g.rotation.y=Math.PI/2;g.userData.dimensions={width:w,depth:d,height:h};scene.add(g);for(const side of[-1,1])box(g,.024,h,d,side*(w/2-.012),h/2,0);box(g,w,.024,d,0,h-.012,0);box(g,w,.08,d,0,.04,0);box(g,w-.048,h-.104,.014,0,h/2+.028,-d/2+.007);return g;}
 const book=cabinet('passage-bookcase',.16,6.55,.8,.28,2.10);for(const y of[.42,.82,1.22,1.62])box(book,.752,.024,.266,0,y,.007);
 for(const x of[-.188,.188])box(book,.368,.32,.022,x,.244,.137,front);
 const books=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),new THREE.MeshStandardMaterial({color:'#ffffff',roughness:.97}),48),o=new THREE.Object3D(),colors=['#d9cbb5','#8a785f','#687162','#b19b7d','#694f43','#b6ada0'];books.name='books-on-four-shelves';for(let row=0;row<4;row++)for(let i=0;i<12;i++){const index=row*12+i,h=.19+(i%4)*.025;o.position.set(-.335+i*.060,.432+row*.40+h/2,.025);o.scale.set(.042,h,.17);o.rotation.z=i===10?.09:0;o.updateMatrix();books.setMatrixAt(index,o.matrix);books.setColorAt(index,new THREE.Color(colors[(i+row)%colors.length]));}books.castShadow=books.receiveShadow=true;book.add(books);
 const drinks=cabinet('passage-drinks-cabinet',.21,7.65,1.1,.38,1.80);box(drinks,1.052,.028,.36,0,.70,.003);for(const y of[1.05,1.41])box(drinks,1.052,.02,.35,0,y,.008);
 for(const side of[-1,1]){const x=side*.263;box(drinks,.514,.60,.024,x,.378,.19,front);box(drinks,.515,1.015,.008,x,1.23,.188,glass);for(const xx of[x-.255,x+.255])box(drinks,.013,1.025,.018,xx,1.23,.197,bronze);box(drinks,.014,.14,.022,side*.025,1.22,.211,bronze);}
 for(const y of[1.04,1.40,1.77])box(drinks,1.02,.006,.012,0,y,-.12,warm);
 const green=new THREE.MeshStandardMaterial({color:'#4c5941',roughness:.22,transparent:true,opacity:.82}),amber=new THREE.MeshStandardMaterial({color:'#a26b35',roughness:.25,transparent:true,opacity:.87}),label=new THREE.MeshStandardMaterial({color:'#e2d1af',roughness:.8});
 const bottleGeo=new THREE.LatheGeometry([[0,0],[.029,0],[.034,.014],[.034,.155],[.015,.185],[.014,.24],[0,.24]].map(p=>new THREE.Vector2(...p)),16);
 for(const [row,y]of[.715,1.065,1.425].entries())for(let i=0;i<5;i++){const x=-.40+i*.19,z=.025,b=mesh(drinks,bottleGeo,i%2?green:amber,x,y,z);b.name='bar-bottle';mesh(drinks,new THREE.CylinderGeometry(.0155,.0155,.025,12),bronze,x,y+.24,z);box(drinks,.045,.055,.002,x,y+.09,z+.034,label);}
 for(const x of[-.22,0,.22]){const g=new THREE.Group();g.position.set(x,.715,.105);drinks.add(g);const cup=mesh(g,new THREE.CylinderGeometry(.027,.018,.067,14,1,true),glass,0,.09,0);mesh(g,new THREE.CylinderGeometry(.003,.003,.055,8),glass,0,.035,0);mesh(g,new THREE.CylinderGeometry(.025,.025,.004,14),glass,0,.006,0);}
 return {groups:[book,drinks],obstacles:[{minX:.02,maxX:.31,minZ:6.15,maxZ:6.95},{minX:.02,maxX:.435,minZ:7.10,maxZ:8.20}]};
}
